using Config;
using System.Collections.Generic;

/// <summary>Explicit example catalog; replace it with product configuration when integrating.</summary>
public static class ShopDemoCatalog
{
    /// <summary>Independent reward image retained with the mall materials.</summary>
    public const string tokenIcon = "Assets/Data/Widgets/Shop/ShopAssets/icon_wupin_zuanshi.png";

    /// <summary>Create local examples without implying real offers or live prices.</summary>
    /// <returns>New independent product objects for the local simulation.</returns>
    public static List<ShopProduct> Create()
    {
        var products = new List<ShopProduct>();
        int[] amounts = new int[] {
            60,
            300,
            980,
            1980,
            3280,
            6480
        };

        for (int i = 0; i < amounts.Length; i++)
        {
            int amount = amounts[i];
            products.Add(new ShopProduct {
                id = i + 1,
                category = ShopCategory.Recharge,
                nameId = Excel.SHOP_TOKEN_AMOUNT,
                price = amount * 10L,
                reward = amount,
                remaining = 99,
                icon = $"Assets/Data/Widgets/Shop/ShopAssets/sc_czsd_icon_{amount}zuanshi_cn.png"
            });
        }

        int[] names = new int[] {
            Excel.SHOP_GIFT_SMALL,
            Excel.SHOP_GIFT_MEDIUM,
            Excel.SHOP_GIFT_LARGE
        };

        for (int i = 0; i < names.Length; i++)
            products.Add(new ShopProduct {
                id = 101 + i,
                category = ShopCategory.Gift,
                nameId = names[i],
                price = 600L * (i + 1),
                reward = 100L * (i + 1),
                remaining = i + 1,
                icon = tokenIcon
            });

        return products;
    }
}

using Oathx.Entity;
using System.Collections.Generic;

/// <summary>Local demonstration state for the reusable mall template.</summary>
[Initialize]
public partial class ShopEntity : XEntity
{
    /// <summary>Catalog supplied by the product or the explicit demo initializer.</summary>
    private List<ShopProduct> products = new List<ShopProduct>();

    /// <summary>Number of products in the owned catalog.</summary>
    public int productCount
    {
        get { return products.Count; }
    }

    /// <summary>Selected catalog category.</summary>
    public ShopCategory category
    { get; private set; }

    /// <summary>Pending product identifier, or zero when no confirmation is open.</summary>
    public int selectedProduct
    { get; private set; }

    /// <summary>Simulated spending balance in minor currency units, never real money.</summary>
    public long demoBalance
    { get; private set; }

    /// <summary>Locally granted tokens, independent of the product wallet.</summary>
    public long demoTokens
    { get; private set; }

    /// <summary>Number of successful local purchases.</summary>
    public int purchaseCount
    { get; private set; }

    /// <summary>Most recent local purchase result.</summary>
    public ShopPurchaseResult result
    { get; private set; }

    /// <summary>Read detached products for the selected category.</summary>
    /// <returns>A catalog snapshot that cannot mutate purchase state.</returns>
    public List<ShopProduct> GetProducts()
    {
        var result = new List<ShopProduct>();
        foreach (var entry in products)
        {
            if (entry.category == category)
            {
                result.Add(new ShopProduct {
                    id = entry.id,
                    category = entry.category,
                    nameId = entry.nameId,
                    price = entry.price,
                    reward = entry.reward,
                    remaining = entry.remaining,
                    icon = entry.icon
                });
            }
        }

        return result;
    }

    /// <summary>Install a validated local catalog without making a service request.</summary>
    /// <param name="catalog">Product definitions owned by this demonstration.</param>
    /// <param name="balance">Simulated balance in minor currency units.</param>
    /// <returns>True when the complete catalog was accepted.</returns>
    public bool InitializeDemo(IEnumerable<ShopProduct> catalog, long balance)
    {
        if (catalog == null || balance < 0)
            return false;

        var entries = new List<ShopProduct>();
        var identifiers = new HashSet<int>();
        foreach (var entry in catalog)
        {
            if (entry == null || entry.id <= 0 || !identifiers.Add(entry.id)
                || entry.price < 0 || entry.reward <= 0 || entry.remaining < 0
                || !System.Enum.IsDefined(typeof(ShopCategory), entry.category))
                return false;

            entries.Add(new ShopProduct {
                id = entry.id,
                category = entry.category,
                nameId = entry.nameId,
                price = entry.price,
                reward = entry.reward,
                remaining = entry.remaining,
                icon = entry.icon
            });
        }

        if (entries.Count == 0)
            return false;

        products = entries;
        demoBalance = balance;
        demoTokens = 0;
        purchaseCount = 0;
        selectedProduct = 0;
        category = entries[0].category;
        result = ShopPurchaseResult.None;

        return true;
    }

    /// <summary>Switch category and cancel any stale pending purchase.</summary>
    /// <param name="value">Requested category.</param>
    /// <returns>True when the category exists in the catalog.</returns>
    public bool SelectCategory(ShopCategory value)
    {
        if (!System.Enum.IsDefined(typeof(ShopCategory), value)
            || !products.Exists(entry => entry.category == value))
            return false;

        category = value;
        selectedProduct = 0;
        result = ShopPurchaseResult.None;

        return true;
    }

    /// <summary>Select an available product for local confirmation.</summary>
    /// <param name="productId">Identifier in the current category.</param>
    /// <returns>True when confirmation can be opened.</returns>
    public bool SelectProduct(int productId)
    {
        if (selectedProduct != 0)
            return false;

        var entry = products.Find(item => item.id == productId && item.category == category);
        if (entry == null || entry.remaining <= 0)
            return false;

        selectedProduct = productId;
        result = ShopPurchaseResult.None;

        return true;
    }

    /// <summary>Cancel confirmation without changing balance or rewards.</summary>
    public void CancelPurchase()
    {
        selectedProduct = 0;
    }

    /// <summary>Confirm one local purchase and consume the pending selection once.</summary>
    /// <returns>The result to present through the product localization table.</returns>
    public ShopPurchaseResult ConfirmPurchase()
    {
        var entry = products.Find(item => item.id == selectedProduct && item.category == category);
        selectedProduct = 0;

        if (entry == null)
        {
            result = ShopPurchaseResult.NoSelection;

            return result;
        }

        if (entry.remaining <= 0)
        {
            result = ShopPurchaseResult.SoldOut;

            return result;
        }

        if (demoBalance < entry.price)
        {
            result = ShopPurchaseResult.InsufficientBalance;

            return result;
        }

        if (demoTokens > long.MaxValue - entry.reward || purchaseCount == int.MaxValue)
        {
            result = ShopPurchaseResult.CapacityExceeded;

            return result;
        }

        demoBalance -= entry.price;
        demoTokens += entry.reward;
        entry.remaining--;
        purchaseCount++;
        result = ShopPurchaseResult.Succeeded;

        return result;
    }
}

/// <summary>Supported categories in the first local mall reference.</summary>
public enum ShopCategory
{
    /// <summary>Token recharge examples.</summary>
    Recharge,

    /// <summary>Limited gift examples.</summary>
    Gift
}

/// <summary>Local purchase outcome without a localized presentation.</summary>
public enum ShopPurchaseResult
{
    /// <summary>No operation has completed.</summary>
    None,

    /// <summary>One simulated transaction was completed.</summary>
    Succeeded,

    /// <summary>No valid confirmation was pending.</summary>
    NoSelection,

    /// <summary>The local purchase limit was reached.</summary>
    SoldOut,

    /// <summary>The simulated spending balance was insufficient.</summary>
    InsufficientBalance,

    /// <summary>The local reward counter cannot represent another grant.</summary>
    CapacityExceeded
}

/// <summary>A local product definition and its remaining purchase limit.</summary>
public class ShopProduct
{
    /// <summary>Stable catalog identifier.</summary>
    public int id
    { get; set; }

    /// <summary>Owning category.</summary>
    public ShopCategory category
    { get; set; }

    /// <summary>CommonText identifier resolved by the presentation layer.</summary>
    public int nameId
    { get; set; }

    /// <summary>Simulated price in minor currency units.</summary>
    public long price
    { get; set; }

    /// <summary>Number of local tokens granted once.</summary>
    public long reward
    { get; set; }

    /// <summary>Remaining local purchase limit.</summary>
    public int remaining
    { get; set; }

    /// <summary>Product image asset path.</summary>
    public string icon
    { get; set; }
}

using Config;
using Oathx.Core;
using Oathx.Entity;
using Oathx.Widget;
using System.Globalization;

/// <summary>Coordinates the local mall reference without payment or network APIs.</summary>
public class ShopSystem : RuntimeSystem
{
    /// <summary>Open the mall and initialize its local demonstration catalog once.</summary>
    /// <returns>True when the page was requested.</returns>
    public override bool OnActive()
    {
        if (!IsActive() || !InitializeDemo())
            return false;

        UISystem.GetSingleton().OpenWidget<UIShop>((widget) => {
            if (widget)
            {
                var vm = widget.vm;
                if (!vm)
                    return;

                vm.CloseClick = (sender) => Close();
                vm.HelpClick = (sender) => ShowMessage(Excel.SHOP_HELP);
                vm.PreviousClick = (sender) => SelectCategory(ShopCategory.Recharge);
                vm.NextClick = (sender) => SelectCategory(ShopCategory.Gift);
                vm.GroupClick = (sender, index) => SelectCategory((ShopCategory)index);
                vm.TabClick = (sender, index) => Refresh();
                vm.Currency1Click = (sender) => ShowMessage(Excel.SHOP_HELP);
                vm.Currency2Click = (sender) => ShowMessage(Excel.SHOP_HELP);
                vm.Currency3Click = (sender) => ShowMessage(Excel.SHOP_HELP);
                vm.AddCurrency1Click = (sender) => ShowMessage(Excel.SHOP_HELP);
                vm.AddCurrency2Click = (sender) => ShowMessage(Excel.SHOP_HELP);
                vm.AddCurrency3Click = (sender) => ShowMessage(Excel.SHOP_HELP);
                vm.GroupTemplate = false;
                vm.TabTemplate = false;
                vm.MessageVisible = true;

                SelectCategory(ShopCategory.Recharge);
                ShowMessage(Excel.SHOP_DEMO_NOTICE);
            }
        });

        return true;
    }

    /// <summary>Cancel the local selection and release all owned views.</summary>
    public override void OnDetive()
    {
        UnsubscribeAll();

        var entity = XEntityManager.GetSingleton().QueryEntity<ShopEntity>();
        if (entity)
            entity.CancelPurchase();

        System.Type[] widgets = new System.Type[] {
            typeof(UIShopPurchase),
            typeof(UIShopGift),
            typeof(UIShopRecharge),
            typeof(UIShop)
        };

        UISystem.GetSingleton().CloseWidget(widgets, immediate: true);
    }

    /// <summary>Refresh the mall and any currently open product list.</summary>
    /// <returns>True when the mall was available.</returns>
    public bool Refresh()
    {
        if (!IsActive() || !UISystem.GetSingleton().TryGetWidget<UIShop>(out var widget))
            return false;

        var vm = widget.vm;
        if (!vm)
            return false;

        var entity = XEntityManager.GetSingleton().QueryEntity<ShopEntity>();
        if (!entity)
            return false;

        vm.Currency1 = Money(entity.demoBalance);
        vm.Currency2 = "0";
        vm.Currency3 = entity.demoTokens.ToString(CultureInfo.InvariantCulture);
        vm.Groups = new VList<VMShopGroup> {
            new VMShopGroup {
                Title = CommonText.Get(Excel.SHOP_RECHARGE),
                Selected = entity.category == ShopCategory.Recharge,
                Unselected = entity.category != ShopCategory.Recharge,
            },
            new VMShopGroup {
                Title = CommonText.Get(Excel.SHOP_GIFTS),
                Selected = entity.category == ShopCategory.Gift,
                Unselected = entity.category != ShopCategory.Gift,
            }
        };
        vm.Tabs = new VList<VMShopTab> {
            new VMShopTab {
                Title = CommonText.Get(entity.category == ShopCategory.Recharge ? Excel.SHOP_RECHARGE : Excel.SHOP_GIFTS),
                Selected = true,
                Unselected = false,
            }
        };

        RefreshProducts(entity);

        return true;
    }

    /// <summary>Switch between the supported local recharge and gift catalogs.</summary>
    /// <param name="category">Requested category.</param>
    /// <returns>True when the child page was requested.</returns>
    public bool SelectCategory(ShopCategory category)
    {
        if (!IsActive())
            return false;

        var entity = XEntityManager.GetSingleton().QueryEntity<ShopEntity>();
        if (!entity)
            return false;

        if (!entity.SelectCategory(category))
            return false;

        System.Type[] widgets = new System.Type[] {
            typeof(UIShopPurchase),
            typeof(UIShopGift),
            typeof(UIShopRecharge)
        };

        UISystem.GetSingleton().CloseWidget(widgets, immediate: true);
        Refresh();

        if (category == ShopCategory.Recharge)
        {
            UISystem.GetSingleton().OpenWidget<UIShopRecharge>((widget) => {
                if (widget)
                {
                    var vm = widget.vm;
                    if (!vm)
                        return;

                    vm.ProductTemplate = false;
                    vm.ProductClick = (sender, index) => SelectProduct(index);

                    Refresh();
                }
            });
        }
        else
        {
            UISystem.GetSingleton().OpenWidget<UIShopGift>((widget) => {
                if (widget)
                {
                    var vm = widget.vm;
                    if (!vm)
                        return;

                    vm.ProductTemplate = false;
                    vm.ProductClick = (sender, index) => SelectProduct(index);

                    Refresh();
                }
            });
        }

        return true;
    }

    /// <summary>Open the local confirmation for one product in the visible list.</summary>
    /// <param name="index">Index within the current category.</param>
    /// <returns>True when a valid product confirmation was requested.</returns>
    public bool SelectProduct(int index)
    {
        if (!IsActive())
            return false;

        if (!UISystem.GetSingleton().TryGetWidget<UIShop>(out var main) || !main.CanInteract())
            return false;

        var entity = XEntityManager.GetSingleton().QueryEntity<ShopEntity>();
        if (!entity)
            return false;

        var products = entity.GetProducts();
        if (index < 0 || index >= products.Count || !entity.SelectProduct(products[index].id))
            return false;

        var product = products[index];

        UISystem.GetSingleton().OpenWidget<UIShopPurchase>((widget) => {
            if (widget)
            {
                var vm = widget.vm;
                if (!vm)
                    return;

                vm.CloseClick = (sender) => CancelPurchase();
                vm.ConfirmClick = (sender) => ConfirmPurchase();
                vm.ConfirmText = CommonText.Get(Excel.SHOP_CONFIRM);
                vm.Price = CommonText.Get(Excel.SHOP_PRICE, Money(product.price));
                vm.Title = ProductTitle(product);
                vm.Icon = product.icon;
                vm.RewardTitle = CommonText.Get(Excel.SHOP_REWARDS);
                vm.RewardName = CommonText.Get(Excel.SHOP_TOKEN_NAME);
                vm.RewardCount = CommonText.Get(Excel.SHOP_COUNT, product.reward);
                vm.RewardIcon = ShopDemoCatalog.tokenIcon;
                vm.AlternatePurchase = false;
                vm.FreeText = false;
                vm.RandomTitle = false;
                vm.RandomRewards = false;
                vm.Discount = false;
                vm.Labels = false;
            }
        });

        return true;
    }

    /// <summary>Confirm the pending local transaction once and refresh the visible catalog.</summary>
    /// <returns>True only when the simulated transaction succeeded.</returns>
    public bool ConfirmPurchase()
    {
        if (!IsActive())
            return false;

        var entity = XEntityManager.GetSingleton().QueryEntity<ShopEntity>();
        if (!entity)
            return false;

        long before = entity.demoTokens;
        var result = entity.ConfirmPurchase();

        CancelPurchase();
        Refresh();
        ShowMessage(result == ShopPurchaseResult.Succeeded ? Excel.SHOP_SUCCESS
            : result == ShopPurchaseResult.InsufficientBalance ? Excel.SHOP_INSUFFICIENT
            : result == ShopPurchaseResult.SoldOut ? Excel.SHOP_SOLD_OUT
            : result == ShopPurchaseResult.CapacityExceeded ? Excel.SHOP_CAPACITY : Excel.SHOP_NO_SELECTION,
            entity.demoTokens - before);

        return result == ShopPurchaseResult.Succeeded;
    }

    /// <summary>Close confirmation without applying a transaction.</summary>
    /// <returns>True when pending selection was cancelled.</returns>
    public bool CancelPurchase()
    {
        var entity = XEntityManager.GetSingleton().QueryEntity<ShopEntity>();
        if (!entity)
            return false;

        entity.CancelPurchase();

        System.Type[] widgets = new System.Type[] {
            typeof(UIShopPurchase)
        };

        UISystem.GetSingleton().CloseWidget(widgets, immediate: true);

        return true;
    }

    /// <summary>Ask the owning coordinator to deactivate this mall.</summary>
    /// <returns>True when a local deactivation event was emitted.</returns>
    public bool Close()
    {
        if (!IsActive())
            return false;

        XPluginUtility.FireEvent(new SystemDetive { type = typeof(ShopSystem) });

        return true;
    }

    /// <summary>Install explicit sample data only when no product catalog exists.</summary>
    /// <returns>True when a catalog is available.</returns>
    private bool InitializeDemo()
    {
        var entity = XEntityManager.GetSingleton().QueryEntity<ShopEntity>();
        if (!entity)
            return false;

        if (entity.productCount > 0)
            return true;

        return entity.InitializeDemo(ShopDemoCatalog.Create(), 100000);
    }

    /// <summary>Publish cell view models without retaining a second copy of entity data.</summary>
    /// <param name="entity">Validated local mall entity.</param>
    private void RefreshProducts(ShopEntity entity)
    {
        if (entity.category == ShopCategory.Recharge && UISystem.GetSingleton().TryGetWidget<UIShopRecharge>(out var recharge))
        {
            var vm = recharge.vm;
            if (vm)
            {
                var items = new VList<VMShopRechargeItem>();
                foreach (var product in entity.GetProducts())
                    items.Add(new VMShopRechargeItem {
                        Title = ProductTitle(product),
                        Price = CommonText.Get(Excel.SHOP_PRICE, Money(product.price)),
                        Item = new VMItemSlot {
                            Icon = product.icon,
                            IconVisible = true,
                            Text = string.Empty
                        },
                        Bonus = string.Empty,
                        FirstPay = false,
                        FirstPayText = CommonText.Get(Excel.SHOP_FIRST_PAY),
                    });

                vm.Products = items;
            }
        }

        if (entity.category == ShopCategory.Gift && UISystem.GetSingleton().TryGetWidget<UIShopGift>(out var gift))
        {
            var vm = gift.vm;
            if (vm)
            {
                var items = new VList<VMShopGiftItem>();
                foreach (var product in entity.GetProducts())
                    items.Add(new VMShopGiftItem {
                        Title = ProductTitle(product),
                        Price = CommonText.Get(Excel.SHOP_PRICE, Money(product.price)),
                        Item = new VMItemSlot {
                            Icon = product.icon,
                            IconVisible = true,
                            Text = CommonText.Get(Excel.SHOP_COUNT, product.reward)
                        },
                        Limit = CommonText.Get(Excel.SHOP_LIMIT, product.remaining),
                        SoldOut = product.remaining == 0,
                        SoldOutText = CommonText.Get(Excel.SHOP_SOLD_OUT),
                    });

                vm.Products = items;
            }
        }
    }

    /// <summary>Display a localized local-operation message.</summary>
    /// <param name="textId">CommonText identifier.</param>
    /// <param name="args">Localized format arguments.</param>
    /// <returns>True when the current mall message was changed.</returns>
    private bool ShowMessage(int textId, params object[] args)
    {
        if (!UISystem.GetSingleton().TryGetWidget<UIShop>(out var widget))
            return false;

        var vm = widget.vm;
        if (!vm)
            return false;

        vm.Message = CommonText.Get(textId, args);

        return true;
    }

    /// <summary>Resolve a catalog title through CommonText.</summary>
    /// <param name="product">Product to present.</param>
    /// <returns>The localized product title.</returns>
    private string ProductTitle(ShopProduct product)
    {
        return CommonText.Get(product.nameId, product.reward);
    }

    /// <summary>Format minor simulated currency units without binary floating point.</summary>
    /// <param name="amount">Amount in minor units.</param>
    /// <returns>An invariant two-decimal amount for a localized price phrase.</returns>
    private string Money(long amount)
    {
        return (amount / 100m).ToString("0.00", CultureInfo.InvariantCulture);
    }
}

using Oathx.Widget;
using System.Collections;
using UnityEngine;

/// <summary>Displays the Shop view through serialized Metadata.</summary>
[Config("Assets/Data/Widgets/Shop/Shop.prefab", WidgetLayer.topmost, cacheWidget: false)]
public class UIShop : UIWidget<VMShop>
{
    /// <summary>Blocks mall input during the original opening interval.</summary>
    [SerializeField]
    private CanvasGroup interaction;

    /// <summary>Read the source opening gate for separately hosted product pages.</summary>
    /// <returns>True after the mall entrance allows input.</returns>
    public bool CanInteract()
    {
        return interaction && interaction.interactable;
    }

    /// <summary>Restart the original half-second opening interaction gate.</summary>
    private void OnEnable()
    {
        if (interaction)
        {
            interaction.interactable = false;

            StartCoroutine(EnableInteraction());
        }
    }

    /// <summary>Release the gate when the view is hidden or destroyed.</summary>
    private void OnDisable()
    {
        StopAllCoroutines();

        if (interaction)
            interaction.interactable = true;
    }

    /// <summary>Restore input after the source opening gate duration.</summary>
    /// <returns>The unscaled opening delay.</returns>
    private IEnumerator EnableInteraction()
    {
        yield return new WaitForSecondsRealtime(0.5f);

        if (interaction)
            interaction.interactable = true;
    }
}

